21	import type { Tenant } from "../server/_support/fixtures";
22	import type { PlanId } from "@/types/billing";
23	
24	let cleanup: () => void;
25	
26	/** `2026-06-01T0{hour}:00:00.000Z` — every test gets its own hour so a scan
27	 * driven by one test's `now` never also matches another test's org. */
28	function nowAtHour(hour: number): Date {
29	  return new Date(Date.UTC(2026, 5, 1, hour, 0, 0, 0));
30	}
31	
32	/** Creates a tenant on `plan` whose digest fires only at `digestHourUtc`, and
33	 * registers it with the usage rollup so `listOrgIdsForRollup` finds it. */
34	async function makeTenant(
35	  slug: string,
36	  digestHourUtc: number,
37	  plan: PlanId = "growth",
38	): Promise<Tenant> {
39	  const tenant = await createTenant(slug, plan);
40	  await orgRepo.updateOrg(tenant.org.id, {
41	    orgId: tenant.org.id,
42	    settings: { digestHourUtc },
43	  });
44	  await usageRepo.recomputeUsage(tenant.org.id);
45	  return tenant;
46	}
47	
48	/** Subscribes a member to the digest by setting one `digestOnly` preference. */
49	async function subscribeToDigest(tenant: Tenant): Promise<void> {
50	  await preferenceRepo.upsertPreference({
51	    orgId: tenant.org.id,
52	    userId: tenant.userIds.member,
53	    kind: "comment_created",
54	    inApp: false,
55	    email: false,
56	    digestOnly: true,
57	  });
58	}
59	
60	async function insertNotificationAt(
61	  tenant: Tenant,
62	  at: Date,
63	  title: string,
64	): Promise<void> {
65	  vi.useFakeTimers();
66	  vi.setSystemTime(at);
67	  try {
68	    await notificationRepo.insertNotification(tenant.org.id, {
69	      orgId: tenant.org.id,
70	      recipientId: tenant.userIds.member,
71	      kind: "comment_created",
72	      title,
73	      body: title,
74	      href: "/issues/1",
75	      actorId: null,
76	      channels: ["email"],
77	    });
78	  } finally {
79	    vi.useRealTimers();
80	  }
81	}
82	
83	/** Pulls a `<td>key</td><td>value</td>` cell out of the generic email table. */
84	function cell(html: string, key: string): string | null {
85	  const match = html.match(new RegExp(`<td>${key}</td><td>([^<]*)</td>`));
86	  return match?.[1] ?? null;
87	}
88	
89	beforeAll(async () => {
90	  cleanup = await useTemporaryDatabase();
91	});
92	
93	afterEach(() => {
94	  vi.restoreAllMocks();
95	  vi.useRealTimers();
96	});
97	
98	afterAll(() => {
99	  cleanup();
100	});
101	
102	describe("jobs/digest-email-job", () => {
103	  it("uses the org's configured digest hour to pick the window", async () => {
104	    const now = nowAtHour(1);
105	    const tenant = await makeTenant("digest-window", 1);
106	    await subscribeToDigest(tenant);
107	
108	    await insertNotificationAt(tenant, new Date(now.getTime() - 12 * 3_600_000), "Recent update");
109	    await insertNotificationAt(tenant, new Date(now.getTime() - 30 * 3_600_000), "Stale update");
110	
111	    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);
112	
113	    await runDigestEmailJob(now);
114	
115	    expect(sendSpy).toHaveBeenCalledTimes(1);
116	    const html = sendSpy.mock.calls[0]?.[0].html ?? "";
117	    expect(cell(html, "entryCount")).toBe("1");
118	    expect(cell(html, "headline")).toBe("Recent update");
119	  });
120	
121	  it("skips an org whose digest hour has not arrived", async () => {
122	    const tenant = await makeTenant("digest-hour-not-yet", 2);
123	    await subscribeToDigest(tenant);
124	    await insertNotificationAt(tenant, new Date(nowAtHour(2).getTime() - 3_600_000), "Fresh");
125	
126	    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);
127	
128	    // A run at an hour that does not match the org's configured hour.
129	    await runDigestEmailJob(nowAtHour(3));
130	
131	    expect(sendSpy).not.toHaveBeenCalled();
132	  });
133	
134	  it("skips an org whose plan does not include digest_email", async () => {
135	    const now = nowAtHour(4);
136	    const tenant = await makeTenant("digest-free-plan", 4, "free");
137	    await subscribeToDigest(tenant);
138	    await insertNotificationAt(tenant, new Date(now.getTime() - 3_600_000), "Fresh");
139	
140	    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);
141	
142	    await runDigestEmailJob(now);
143	
144	    expect(sendSpy).not.toHaveBeenCalled();
145	  });
146	
147	  it("sends nothing to a recipient with an empty window", async () => {
148	    const now = nowAtHour(5);
149	    const tenant = await makeTenant("digest-empty-window", 5);
150	    await subscribeToDigest(tenant);
151	    // Nothing unread inside the window at all.
152	
153	    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);
154	
155	    const result = await runDigestEmailJob(now);
156	
157	    expect(sendSpy).not.toHaveBeenCalled();
158	    expect(result.processed).toBe(0);
159	  });
160	
161	  it("caps the entries at DIGEST_MAX_ENTRIES", async () => {
162	    const now = nowAtHour(6);
163	    const tenant = await makeTenant("digest-cap", 6);
164	    await subscribeToDigest(tenant);
165	
166	    for (let i = 0; i < DIGEST_MAX_ENTRIES + 5; i += 1) {
167	      await insertNotificationAt(
168	        tenant,
169	        new Date(now.getTime() - (i + 1) * 1_000),
170	        `Update ${i}`,
171	      );
172	    }
173	
174	    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);
175	
176	    await runDigestEmailJob(now);
177	
178	    expect(sendSpy).toHaveBeenCalledTimes(1);
179	    const html = sendSpy.mock.calls[0]?.[0].html ?? "";
180	    expect(cell(html, "entryCount")).toBe(String(DIGEST_MAX_ENTRIES));
181	  });
182	
183	  it("does not resend a digest for an already-covered window", async () => {
184	    const now = nowAtHour(7);
185	    const tenant = await makeTenant("digest-no-resend", 7);
186	    await subscribeToDigest(tenant);
187	    await insertNotificationAt(tenant, new Date(now.getTime() - 3_600_000), "Once");
188	
189	    const sendSpy = vi.spyOn(emailService, "sendEmail").mockResolvedValue(undefined);
190	
191	    await runDigestEmailJob(now);
192	    expect(sendSpy).toHaveBeenCalledTimes(1);
193	
194	    await runDigestEmailJob(now);
195	    expect(sendSpy).toHaveBeenCalledTimes(1);
196	  });
197	
198	  it("constructs its own actor rather than reading cookies", async () => {
