export function dayStart(day: string, timeZone: string): IsoTimestamp {
  return toIsoTimestamp(new Date(localInstant(day, 0, timeZone)));
}

/** Moves a `YYYY-MM-DD` calendar date by whole days. */
export function shiftDays(day: string, days: number): string {
  const [year, month, date] = parseDay(day);
  const shifted = new Date(Date.UTC(year, month - 1, date + days));
  return formatDay(
    shifted.getUTCFullYear(),
    shifted.getUTCMonth() + 1,
    shifted.getUTCDate(),
  );
}

/**
 * True once the calendar day holding `dueAt` has ended on the zone's clock. A
 * due date is a whole day, so on that day itself the issue is not overdue yet,
 * whatever time of day `dueAt` names.
 */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  return localDate(dueAt, timeZone) < dayOf(reference.getTime(), timeZone);
}

export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/**
 * The window a digest covers. It ends at the most recent `digestHour:00` on the
 * zone's clock at or before `reference` — today's if that hour has passed,
 * yesterday's otherwise — and starts at the same hour on the calendar day
 * before. Across a DST change the window is 23 or 25 hours long.
 */
export function digestWindow(
  digestHour: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHour) || digestHour < 0 || digestHour > 23) {
    throw new RangeError(`digest hour must be 0-23, got ${digestHour}`);
  }

  const today = dayOf(reference.getTime(), timeZone);
  let endDay = today;
  let end = localInstant(today, digestHour, timeZone);
  if (end > reference.getTime()) {
    endDay = shiftDays(today, -1);
    end = localInstant(endDay, digestHour, timeZone);
  }
  const start = localInstant(shiftDays(endDay, -1), digestHour, timeZone);

  return {
    start: toIsoTimestamp(new Date(start)),
    end: toIsoTimestamp(new Date(end)),
  };
}

