  try {
    for (const statement of readMigrationStatements()) {
      sqlite.exec(statement);
    }
    // `CREATE TABLE IF NOT EXISTS` leaves a table created before a column
    // existed exactly as it was, so the late-added zone column is backfilled.
    addColumnIfMissing(sqlite, "organizations", "time_zone", "TEXT NOT NULL DEFAULT 'UTC'");
  } finally {
    sqlite.close();
  }
}

/** SQLite has no `ADD COLUMN IF NOT EXISTS`, so the table is inspected first. */
function addColumnIfMissing(
  sqlite: Database.Database,
  table: string,
  column: string,
  definition: string,
): void {
  const existing = sqlite.pragma(`table_info(${table})`) as readonly { name: string }[];
  if (existing.some((row) => row.name === column)) return;
  sqlite.exec(`ALTER TABLE ${table} ADD COLUMN ${column} ${definition}`);
}

