import { DatePicker } from "@/components/ui/date-picker";
import { useWorkspaceTimeZone } from "@/hooks/use-org";
import { dayStart, isOverdue, localDate, parseIso, shiftDays } from "@/lib/date";
import { toIsoTimestamp } from "@/types/common";
import type { IsoTimestamp } from "@/types/common";
import type { ReactElement } from "react";

export type IssueDueDateFieldProps = {
  value: IsoTimestamp | null;
  onChange: (value: IsoTimestamp | null) => void;
};

/** The picker speaks `YYYY-MM-DD` on the workspace clock; the domain stores full ISO timestamps. */
export function toDateInputValue(
  value: IsoTimestamp | null,
  timeZone = "UTC",
): string | null {
  return value === null ? null : localDate(value, timeZone);
}

export function fromDateInputValue(
  value: string | null,
  timeZone = "UTC",
): IsoTimestamp | null {
  if (value === null || value.length === 0) return null;
  // End of the chosen day on the workspace clock: an issue due "today" is not
  // overdue at 09:00.
  const nextDay = parseIso(dayStart(shiftDays(value, 1), timeZone));
  return toIsoTimestamp(new Date(nextDay.getTime() - 1));
}

export function IssueDueDateField(
  props: IssueDueDateFieldProps,
): ReactElement | null {
  const timeZone = useWorkspaceTimeZone();
  const overdue = isOverdue(props.value, new Date(), timeZone);

  return (
    <div className="space-y-1">
      <DatePicker
        value={toDateInputValue(props.value, timeZone)}
        placeholder="No due date"
        onChange={(value) => props.onChange(fromDateInputValue(value, timeZone))}
      />

