toolUseResult.originalFile:
/**
 * Organization overview: recent issues, project stats and usage.
 *
 * Owner D. Three panels, each behind its own permission — a viewer sees the
 * issues and the projects but not the usage meters, because usage is billing
 * information.
 *
 * Must call (do not reimplement): can
 */

import Link from "next/link";
import type { Metadata } from "next";
import { IssueCard } from "@/components/domain/issue/issue-card";
import { ProjectCard } from "@/components/domain/project/project-card";
import { UsagePanel } from "@/components/domain/billing/usage-panel";
import { EmptyState } from "@/components/ui/empty-state";
import { can } from "@/lib/permissions";
import { getBillingSummary } from "@/server/services/billing-service";
import { listIssues } from "@/server/services/issue-service";
import { listProjects } from "@/server/services/project-service";
import type { BillingSummary } from "@/types/billing";
import { loadTenantContext } from "./_lib/tenant-context";

type PageParams = { orgSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Overview",
};

const RECENT_ISSUE_LIMIT = 8;
const PROJECT_LIMIT = 6;

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  await props.searchParams;

  const { org, actor } = await loadTenantContext(orgSlug);

  const mayReadBilling = can(actor, "org:manage_billing", {
    kind: "billing",
    orgId: org.id,
  });

  const [issues, projects, billing] = await Promise.all([
    listIssues(actor, {
      orgId: org.id,
      assigneeId: actor.userId,
      status: ["todo", "in_progress", "in_review"],
      limit: RECENT_ISSUE_LIMIT,
    }),
    listProjects(actor, { orgId: org.id, limit: PROJECT_LIMIT }),
    mayReadBilling
      ? getBillingSummary(actor, org.id)
      : Promise.resolve<BillingSummary | null>(null),
  ]);

  return (
    <div className="space-y-12">
      <header>
        <h1 className="text-2xl font-semibold tracking-tight">{org.name}</h1>
        <p className="mt-1 text-sm text-slate-600">
          {projects.total} projects · {issues.total} issues assigned to you
        </p>
      </header>

      <section>
        <div className="mb-4 flex items-baseline justify-between">
          <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">
            Assigned to you
          </h2>
          <Link href={`/${orgSlug}/issues`} className="text-sm text-indigo-600">
            All issues
          </Link>
        </div>

        {issues.items.length === 0 ? (
          <EmptyState
            title="Nothing on your plate"
            description="Issues assigned to you show up here as soon as somebody picks you."
          />
        ) : (
          <ul className="space-y-2">
            {issues.items.map((issue) => (
              <li key={issue.id}>
                <IssueCard
                  issue={issue}
                  href={`/${orgSlug}/issues?issue=${issue.id}`}
                  compact
                />
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <div className="mb-4 flex items-baseline justify-between">
          <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">
            Projects
          </h2>
          <Link href={`/${orgSlug}/projects`} className="text-sm text-indigo-600">
            All projects
          </Link>
        </div>

        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {projects.items.map((row) => (
            <ProjectCard
              key={row.project.id}
              project={row.project}
              stats={row.stats}
              href={`/${orgSlug}/projects/${row.project.slug}`}
              actor={actor}
            />
          ))}
        </div>
      </section>

      {billing !== null ? (
        <section>
          <h2 className="mb-4 text-sm font-semibold uppercase tracking-wide text-slate-500">
            Usage
          </h2>
          <UsagePanel summary={billing} />
        </section>
      ) : null}
    </div>
  );
}

/**
 * Project overview.
 *
 * Owner D. Counters from `ProjectStats` plus the most recently updated issues.
 * The header itself is rendered by the layout, so this page is only the body.
 */

import Link from "next/link";
import type { Metadata } from "next";
import { IssueCard } from "@/components/domain/issue/issue-card";
import { EmptyState } from "@/components/ui/empty-state";
import { listIssues } from "@/server/services/issue-service";
import { loadProjectContext } from "../../_lib/project-context";

type PageParams = { orgSlug: string; projectSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Project overview",
};

const RECENT_LIMIT = 10;

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug, projectSlug } = await props.params;
  await props.searchParams;

  const { org, actor, project, stats } = await loadProjectContext(
    orgSlug,
    projectSlug,
  );

  const recent = await listIssues(actor, {
    orgId: org.id,
    projectId: project.id,
    limit: RECENT_LIMIT,
  });

  return (
    <div className="space-y-10">
      <dl className="grid grid-cols-3 gap-4">
        <Stat label="Open" value={stats.openIssues} />
        <Stat label="Closed" value={stats.closedIssues} />
        <Stat label="Overdue" value={stats.overdueIssues} />
      </dl>

      {project.description !== null ? (
        <p className="max-w-2xl text-sm text-slate-600">{project.description}</p>
      ) : null}

      <section>
        <div className="mb-4 flex items-baseline justify-between">
          <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">
            Recently updated
          </h2>
          <Link
            href={`/${orgSlug}/projects/${projectSlug}/issues`}
            className="text-sm text-indigo-600"
          >
            All issues
          </Link>
        </div>

        {recent.items.length === 0 ? (
          <EmptyState
            title="No issues in this project yet"
            description="File the first one and it will show up here."
          />
        ) : (
          <ul className="space-y-2">
            {recent.items.map((issue) => (
              <li key={issue.id}>
                <IssueCard
                  issue={issue}
                  href={`/${orgSlug}/projects/${projectSlug}/issues/${issue.number}`}
                  compact
                />
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

function Stat(props: { label: string; value: number }) {
  return (
    <div className="rounded-md border border-slate-200 bg-white px-4 py-3">
      <dt className="text-xs uppercase tracking-wide text-slate-500">
        {props.label}
      </dt>
      <dd className="mt-1 text-2xl font-semibold">{props.value}</dd>
    </div>
  );
}

/**
 * Issue detail with the comment thread and activity panel.
 *
 * Owner D. The URL carries the human-facing issue *number*, not the ULID, so
 * the number is resolved to a row inside this project before anything else —
 * that lookup is also the tenant boundary.
 *
 * Must call (do not reimplement): can
 */

import { notFound } from "next/navigation";
import type { Metadata } from "next";
import { createCommentAction } from "@/actions/comments/create-comment";
import { deleteCommentAction } from "@/actions/comments/delete-comment";
import { CommentComposer } from "@/components/domain/comment/comment-composer";
import { CommentThread } from "@/components/domain/comment/comment-thread";
import { IssueActivityPanel } from "@/components/domain/issue/issue-activity-panel";
import { IssueDetail } from "@/components/domain/issue/issue-detail";
import { can } from "@/lib/permissions";
import { findIssueByNumber } from "@/server/repositories/issue-repository";
import { listActivityForSubject } from "@/server/repositories/activity-repository";
import { findUserById } from "@/server/repositories/user-repository";
import { getThread } from "@/server/services/comment-service";
import { getIssue } from "@/server/services/issue-service";
import { listMembers } from "@/server/services/member-service";
import type { CommentId } from "@/types/common";
import type { User } from "@/types/member";
import { loadProjectContext } from "../../../../_lib/project-context";

type PageParams = {
