it("treats a null due date as never overdue", () => {
  expect(isOverdue(null, REFERENCE)).toBe(false);
});

it("is overdue only once the due day has ended, not at the due instant", () => {
  // Still the same calendar day as the reference, so the day is not over yet.
  expect(isOverdue(iso("2026-03-15T11:59:59.000Z"), REFERENCE)).toBe(false);
  expect(isOverdue(iso("2026-03-15T00:00:00.000Z"), REFERENCE)).toBe(false);
  expect(isOverdue(iso("2026-03-14T23:59:59.000Z"), REFERENCE)).toBe(true);
});

it("reads the due day on the workspace clock", () => {
  // 05:00 on the 15th in Tokyo, but still the 14th in UTC.
  const due = iso("2026-03-14T20:00:00.000Z");
  expect(isOverdue(due, REFERENCE)).toBe(true);
  expect(isOverdue(due, REFERENCE, "Asia/Tokyo")).toBe(false);
});

it("returns the calendar date of an instant on the workspace clock", () => {
  const late = iso("2026-03-15T23:30:00.000Z");
  expect(localDate(late, "UTC")).toBe("2026-03-15");
  expect(localDate(late, "Asia/Tokyo")).toBe("2026-03-16");
  expect(localDate(late, "America/New_York")).toBe("2026-03-15");
});

it("finds where the workspace's local day began", () => {
  expect(startOfLocalDay(REFERENCE, "UTC")).toBe("2026-03-15T00:00:00.000Z");
  // 21:00 on the 15th in Tokyo: that day began at 00:00 JST, 15:00Z the day before.
  expect(startOfLocalDay(REFERENCE, "Asia/Tokyo")).toBe("2026-03-14T15:00:00.000Z");
});

it("measures a local day across a DST change in its real length", () => {
  // New York springs forward at 02:00 EST on 8 March, so that day is 23 hours.
  const sameDay = new Date("2026-03-08T12:00:00.000Z");
  expect(startOfLocalDay(sameDay, "America/New_York")).toBe("2026-03-08T05:00:00.000Z");
  expect(startOfLocalDay(new Date("2026-03-09T12:00:00.000Z"), "America/New_York")).toBe(
    "2026-03-09T04:00:00.000Z",
  );
});

it("recognises IANA zone names and refuses the rest", () => {
  expect(isValidTimeZone("Asia/Tokyo")).toBe(true);
  expect(isValidTimeZone("Mars/Olympus")).toBe(false);
  expect(() => assertTimeZone("Mars/Olympus")).toThrow(RangeError);
  expect(() => assertTimeZone("Asia/Tokyo")).not.toThrow();
});

