describe("verification (temporary)", () => {
  it("schema defaults and rejects unknown zones", () => {
    expect(organizationSettingsSchema.parse({}).timeZone).toBe("UTC");
    expect(organizationSettingsSchema.safeParse({ timeZone: "Mars/Olympus" }).success).toBe(false);
    const orgId = "01ARZ3NDEKTSV4RRFFQ69G5FAV";
    const patch = updateOrganizationSchema.parse({ orgId, settings: { digestHourUtc: 9 } });
    expect(patch.settings).toEqual({ digestHourUtc: 9 });
    const zoned = updateOrganizationSchema.parse({ orgId, settings: { timeZone: "Asia/Tokyo" } });
    expect(zoned.settings).toEqual({ timeZone: "Asia/Tokyo" });
    expect(updateOrganizationSchema.safeParse({ orgId, settings: { timeZone: "Nope/Zone" } }).success).toBe(false);
  });

  it("stores the zone, refuses bad zones without writing, and reads it back", async () => {
    const tenant = await createTenant("tz-store");
    const before = await orgRepo.findOrgById(tenant.org.id);
    expect(before?.settings.timeZone).toBe("UTC");

    await expect(
      orgRepo.updateOrg(tenant.org.id, { orgId: tenant.org.id, settings: { timeZone: "Mars/Olympus" } }),
    ).rejects.toBeInstanceOf(RangeError);
    expect((await orgRepo.findOrgById(tenant.org.id))?.settings.timeZone).toBe("UTC");

    const updated = await organizationService.updateOrganization(tenant.actors.owner, {
      orgId: tenant.org.id,
      settings: { timeZone: "Asia/Tokyo" },
    });
    expect(updated.settings.timeZone).toBe("Asia/Tokyo");
    expect((await orgRepo.findOrgById(tenant.org.id))?.settings.timeZone).toBe("Asia/Tokyo");

    // A later patch that omits the zone keeps it.
    await orgRepo.updateOrg(tenant.org.id, { orgId: tenant.org.id, settings: { digestHourUtc: 9 } });
    expect((await orgRepo.findOrgById(tenant.org.id))?.settings.timeZone).toBe("Asia/Tokyo");
  });

  it("overdue follows the workspace clock and the counter excludes closed issues", async () => {
    const tenant = await createTenant("tz-overdue");
    await usageRepo.recomputeUsage(tenant.org.id);
    await orgRepo.updateOrg(tenant.org.id, { orgId: tenant.org.id, settings: { timeZone: "Asia/Tokyo" } });

    // 2026-06-01T07:00Z is 16:00 JST on 1 June. This is 05:00 JST on 1 June: day not over.
    const sameDay = await insertIssue(tenant, "same local day", "2026-05-31T20:00:00.000Z");
    // 2026-05-31T14:59Z is 23:59 JST on 31 May: that day has ended.
    const ended = await insertIssue(tenant, "ended locally", "2026-05-31T14:59:00.000Z");
    const closed = await insertIssue(tenant, "closed", "2026-05-01T00:00:00.000Z", "done");

    const now = new Date("2026-06-01T07:00:00.000Z");
    const overdue = await issueRepo.listOverdueIssues(tenant.org.id, toIsoTimestamp(now));
    const ids = overdue.map((row) => row.id);
    expect(ids).toContain(ended.id);
    expect(ids).not.toContain(sameDay.id);
    expect(ids).not.toContain(closed.id);

    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(now);
    const stats = await projectRepo.getProjectStats(tenant.org.id, tenant.project.id);
    vi.useRealTimers();
    expect(stats.overdueIssues).toBe(1);

    const seen: string[] = [];
    const off = subscribe("issue.overdue", (payload) => {
      seen.push(payload.issueId);
    });
    await runOverdueIssueJob(now);
    off();
    expect(seen).toContain(ended.id);
    expect(seen).not.toContain(sameDay.id);
  });

  it("digest hour follows the org clock", async () => {
    const tenant = await createTenant("tz-digest", "growth");
    await orgRepo.updateOrg(tenant.org.id, {
      orgId: tenant.org.id,
      settings: { timeZone: "Asia/Tokyo", digestHourUtc: 7 },
    });
    const org = (await orgRepo.findOrgById(tenant.org.id))!;
    // 22:00Z on 31 May is 07:00 JST on 1 June.
    expect(shouldRunForOrg(org, new Date("2026-05-31T22:00:00.000Z"))).toBe(true);
    expect(shouldRunForOrg(org, new Date("2026-06-01T07:00:00.000Z"))).toBe(false);
  });

  it("groups the feed by the zone's day", () => {
    const build = (id: string, occurredAt: string): ActivityEvent => ({
      id: id as ActivityEvent["id"],
      orgId: "o" as ActivityEvent["orgId"],
      action: "issue.created",
      actorId: null,
      subjectKind: "issue",
      subjectId: "s",
      projectId: null,
      summary: "x",
      metadata: {},
      occurredAt: occurredAt as ActivityEvent["occurredAt"],
    });
    const groups = groupByDay(
      [build("a", "2026-01-01T20:00:00.000Z"), build("b", "2026-01-01T23:00:00.000Z"), build("c", "2026-01-01T10:00:00.000Z")],
      "Asia/Tokyo",
    );
    expect(groups.map((g) => g.day)).toEqual(["2026-01-02", "2026-01-01"]);
    expect(groups[0]?.events.map((e) => e.id)).toEqual(["a", "b"]);
  });

  it("migrates a database created before the zone column existed", async () => {
    const dir = mkdtempSync(join(tmpdir(), "tf-migrate-"));
    const path = join(dir, "old.db");
    const old = new Database(path);
    old.exec(`CREATE TABLE organizations (
      id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL, slug TEXT NOT NULL, owner_id TEXT NOT NULL,
      plan TEXT NOT NULL DEFAULT 'free', logo_url TEXT, trial_ends_at TEXT,
      default_issue_status TEXT NOT NULL DEFAULT 'backlog', allow_public_projects INTEGER NOT NULL DEFAULT 0,
      require_two_factor INTEGER NOT NULL DEFAULT 0, digest_hour_utc INTEGER NOT NULL DEFAULT 7,
      enabled_flag_overrides TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
      archived_at TEXT)`);
    old.exec(`INSERT INTO organizations (id, name, slug, owner_id, created_at, updated_at) VALUES ('o1','A','a','u','2026-01-01T00:00:00.000Z','2026-01-01T00:00:00.000Z')`);
    old.close();

    await runMigrations(path);
    await runMigrations(path);
    const check = new Database(path);
    const cols = (check.pragma("table_info(organizations)") as { name: string }[]).map((c) => c.name);
    expect(cols).toContain("time_zone");
    expect((check.prepare("SELECT time_zone FROM organizations WHERE id='o1'").get() as { time_zone: string }).time_zone).toBe("UTC");
    check.close();
    rmSync(dir, { recursive: true, force: true });
  });
});

