/** The workspace time zone: defaulted, validated, and never reset by a partial patch. */
import { describe, expect, it } from "vitest";
import {
  organizationSettingsSchema,
  updateOrganizationSchema,
} from "@/schemas/organization";

const ORG = "01HZZZMMMMMMMMMMMMMMMMMMMM";

describe("schemas/organization", () => {
  it("defaults the workspace zone to UTC and accepts IANA names", () => {
    expect(organizationSettingsSchema.parse({}).timeZone).toBe("UTC");
    expect(organizationSettingsSchema.parse({ timeZone: "Asia/Tokyo" }).timeZone).toBe(
      "Asia/Tokyo",
    );
  });

  it("rejects a zone name Intl does not recognise", () => {
    expect(organizationSettingsSchema.safeParse({ timeZone: "Mars/Olympus" }).success).toBe(false);
    expect(
      updateOrganizationSchema.safeParse({ orgId: ORG, settings: { timeZone: "Mars/Olympus" } })
        .success,
    ).toBe(false);
  });

  it("leaves the stored zone alone when a patch does not name it", () => {
    const patch = updateOrganizationSchema.parse({ orgId: ORG, settings: { digestHourUtc: 9 } });
    expect(patch.settings?.digestHourUtc).toBe(9);
    expect(patch.settings).not.toHaveProperty("timeZone");
  });
});

